-- Release-review repairs for migrations 0169: a final-game substitute is a
-- valid schedule amendment, while a current-game forfeit must be current for
-- both participants and must disappear from their score-entry task lists.

create or replace function public.preview_event_schedule_amendment_v1(
  p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_operation_kind text,
  p_rule_basis text,p_director_reason text,p_proposed_schedule jsonb,p_expected_version integer
) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_prior jsonb;v_changed integer;v_total integer;v_allowed_repeat integer:=1;
begin
  if p_actor_id is null or p_operation_kind not in('omitted_player_before_play','late_player_before_game_two','odd_field_first_sitout_makeup','early_departure_substitute','odd_field_extra_games','mixed_rotation_repair','reinstatement_future_games')
    or length(trim(p_rule_basis)) not between 1 and 500 or length(trim(p_director_reason)) not between 1 and 1000
    or jsonb_typeof(p_proposed_schedule)<>'array' or p_expected_version is null or p_expected_version<0 then return jsonb_build_object('status','rejected','code','invalid_request');end if;
  if not exists(select 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director')) then return jsonb_build_object('status','rejected','code','not_director');end if;
  if app.event_play_state_v1(p_event_id)='finalized' or not exists(select 1 from app.events where id=p_event_id and tournament_id=p_tournament_id) then return jsonb_build_object('status','rejected','code','event_unavailable');end if;
  if(select count(*) from app.event_schedule_amendment_versions where event_id=p_event_id)<>p_expected_version then return jsonb_build_object('status','rejected','code','stale_schedule_version');end if;
  v_prior:=app.schedule_snapshot_v1(p_event_id);v_total:=jsonb_array_length(v_prior);
  if jsonb_array_length(p_proposed_schedule)<>v_total or(select count(distinct(item->>'gameId')::uuid)from jsonb_array_elements(p_proposed_schedule)item)<>v_total or exists(select 1 from jsonb_array_elements(p_proposed_schedule)item where not exists(select 1 from app.event_schedule_games where event_id=p_event_id and canonical_game_id=(item->>'gameId')::uuid)) then return jsonb_build_object('status','rejected','code','incomplete_schedule');end if;
  if exists(select 1 from jsonb_array_elements(p_proposed_schedule)item where(item->>'sideAParticipantId')::uuid=(item->>'sideBParticipantId')::uuid or coalesce(item->>'sideATableSeat','')!~'^[A-Za-z0-9]+-[0-9]+$' or coalesce(item->>'sideBTableSeat','')!~'^[A-Za-z0-9]+-[0-9]+$' or not exists(select 1 from app.event_participants where id=(item->>'sideAParticipantId')::uuid and event_id=p_event_id and tournament_id=p_tournament_id) or not exists(select 1 from app.event_participants where id=(item->>'sideBParticipantId')::uuid and event_id=p_event_id and tournament_id=p_tournament_id)) then return jsonb_build_object('status','rejected','code','invalid_assignment');end if;
  if exists(with expanded as(select(item->>'gameNumber')::integer game_number,(item->>'sideAParticipantId')::uuid participant_id,item->>'sideATableSeat' seat from jsonb_array_elements(p_proposed_schedule)item union all select(item->>'gameNumber')::integer,(item->>'sideBParticipantId')::uuid,item->>'sideBTableSeat' from jsonb_array_elements(p_proposed_schedule)item)select 1 from expanded group by game_number,participant_id having count(*)>1)
    or exists(with expanded as(select(item->>'gameNumber')::integer game_number,item->>'sideATableSeat' seat from jsonb_array_elements(p_proposed_schedule)item union all select(item->>'gameNumber')::integer,item->>'sideBTableSeat' from jsonb_array_elements(p_proposed_schedule)item)select 1 from expanded group by game_number,seat having count(*)>1) then return jsonb_build_object('status','rejected','code','round_conflict');end if;
  v_allowed_repeat:=case when p_operation_kind='early_departure_substitute' then 2 else 1 end;
  if exists(with pairs as(select least((item->>'sideAParticipantId')::uuid,(item->>'sideBParticipantId')::uuid) low_id,greatest((item->>'sideAParticipantId')::uuid,(item->>'sideBParticipantId')::uuid)high_id from jsonb_array_elements(p_proposed_schedule)item)select 1 from pairs group by low_id,high_id having count(*)>v_allowed_repeat) then return jsonb_build_object('status','rejected','code','duplicate_opponent');end if;
  select count(*) into v_changed from jsonb_array_elements(p_proposed_schedule)item join jsonb_array_elements(v_prior)old on old->>'gameId'=item->>'gameId' where(item->>'sideAParticipantId',item->>'sideBParticipantId',item->>'sideATableSeat',item->>'sideBTableSeat',coalesce((item->>'standingsEligible')::boolean,true)) is distinct from(old->>'sideAParticipantId',old->>'sideBParticipantId',old->>'sideATableSeat',old->>'sideBTableSeat',coalesce((old->>'standingsEligible')::boolean,true));
  if v_changed=0 then return jsonb_build_object('status','rejected','code','unchanged_schedule');end if;
  if exists(select 1 from jsonb_array_elements(p_proposed_schedule)item join jsonb_array_elements(v_prior)old on old->>'gameId'=item->>'gameId' join app.canonical_games game on game.id=(item->>'gameId')::uuid where(item->>'sideAParticipantId',item->>'sideBParticipantId',item->>'sideATableSeat',item->>'sideBTableSeat') is distinct from(old->>'sideAParticipantId',old->>'sideBParticipantId',old->>'sideATableSeat',old->>'sideBTableSeat') and(game.state<>'pending' or exists(select 1 from app.score_submissions where canonical_game_id=game.id)or exists(select 1 from app.card_scorelines where canonical_game_id=game.id)or app.game_is_authoritatively_resolved_v1(game.id)))then return jsonb_build_object('status','rejected','code','resolved_game_immutable');end if;
  return jsonb_build_object('status','schedule_amendment_preview','eventId',p_event_id,'expectedVersion',p_expected_version,'affectedGameCount',v_changed,'unaffectedGameCount',v_total-v_changed,'priorSchedule',v_prior,'proposedSchedule',p_proposed_schedule,'directorDecisionRequired',p_operation_kind='mixed_rotation_repair');
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return jsonb_build_object('status','rejected','code','invalid_schedule');
end $$;
revoke all on function public.preview_event_schedule_amendment_v1(uuid,uuid,uuid,text,text,text,jsonb,integer) from public,anon,authenticated;
grant execute on function public.preview_event_schedule_amendment_v1(uuid,uuid,uuid,text,text,text,jsonb,integer) to service_role;

create or replace function public.record_operational_forfeit_v1(p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_game_id uuid,p_forfeit_id uuid,p_winner_participant_id uuid,p_departing_participant_id uuid,p_rule_case text,p_director_reason text,p_idempotency_key uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_game app.canonical_games%rowtype;v_hash text;v_prior app.operation_receipts%rowtype;v_receipt uuid:=extensions.gen_random_uuid();v_response jsonb;v_round integer;v_max_round integer;
begin
  if p_actor_id is null or p_forfeit_id is null or p_idempotency_key is null or p_rule_case not in('early_departure_current_game','playoff_absence_5','playoff_absence_20','playoff_absence_35')or length(trim(p_director_reason))not between 1 and 1000 then return jsonb_build_object('status','rejected','code','invalid_request');end if;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_array('record_operational_forfeit_v1',p_actor_id::text,p_tournament_id::text,p_event_id::text,p_game_id::text,p_forfeit_id::text,p_winner_participant_id::text,p_departing_participant_id::text,p_rule_case,p_director_reason)::text,'utf8'),'sha256'),'hex');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_actor_id::text||':'||p_idempotency_key::text,0));perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('operational-forfeit:'||p_game_id::text,0));
  perform 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director')for update;if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
  select*into v_prior from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_idempotency_key;if found then if v_prior.request_hash<>v_hash then return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;return v_prior.response_payload;end if;
  select*into v_game from app.canonical_games where id=p_game_id and event_id=p_event_id and tournament_id=p_tournament_id for update;
  if not found or p_winner_participant_id not in(v_game.side_a_participant_id,v_game.side_b_participant_id)or p_departing_participant_id not in(v_game.side_a_participant_id,v_game.side_b_participant_id)or p_winner_participant_id=p_departing_participant_id then return jsonb_build_object('status','rejected','code','game_unavailable');end if;
  if app.event_play_state_v1(p_event_id)<>'in_progress' or app.game_is_authoritatively_resolved_v1(p_game_id)or exists(select 1 from app.score_submissions where canonical_game_id=p_game_id)or app.participant_game_progression_v1(p_game_id,p_winner_participant_id)is distinct from'current' or app.participant_game_progression_v1(p_game_id,p_departing_participant_id)is distinct from'current' then return jsonb_build_object('status','rejected','code','game_not_forfeitable');end if;
  select round_number into v_round from app.rounds where id=v_game.round_id;select max(round_number)into v_max_round from app.rounds where event_id=p_event_id;if p_rule_case='early_departure_current_game'and v_round=v_max_round then return jsonb_build_object('status','rejected','code','final_game_requires_substitute');end if;
  v_response:=jsonb_build_object('status','operational_forfeit_recorded','eventId',p_event_id,'gameId',p_game_id,'forfeitId',p_forfeit_id,'winnerParticipantId',p_winner_participant_id,'gamePoints',2,'spreadPoints',10);
  insert into app.operation_receipts(id,actor_profile_id,tournament_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at)values(v_receipt,p_actor_id,p_tournament_id,'record_operational_forfeit_v1',p_forfeit_id,v_hash,p_idempotency_key,'accepted',v_response,clock_timestamp());
  insert into app.operational_game_forfeits(id,tournament_id,event_id,canonical_game_id,winner_participant_id,departing_participant_id,rule_case,director_reason,actor_profile_id,operation_receipt_id)values(p_forfeit_id,p_tournament_id,p_event_id,p_game_id,p_winner_participant_id,p_departing_participant_id,p_rule_case,trim(p_director_reason),p_actor_id,v_receipt);
  insert into app.audit_events(tournament_id,actor_profile_id,canonical_game_id,operation_receipt_id,entity_type,entity_id,action,after_state)values(p_tournament_id,p_actor_id,p_game_id,v_receipt,'operational_game_forfeit',p_forfeit_id,'operational_forfeit_recorded',v_response);return v_response;
end $$;
revoke all on function public.record_operational_forfeit_v1(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.record_operational_forfeit_v1(uuid,uuid,uuid,uuid,uuid,uuid,uuid,text,text,uuid) to service_role;

create or replace function public.get_my_assigned_games_v1(p_tournament_id uuid)
returns jsonb language sql stable security definer set search_path='' as $$
with base as(select app.get_my_assigned_games_pre_progression_v1(p_tournament_id)payload)select case when payload is null then null else jsonb_set(payload,'{games}',coalesce((select jsonb_agg(item.game||jsonb_build_object('progressionStatus',progress.status,'nextAction',case when progress.status='not_started'then'event_not_started' when progress.status='upcoming'then'upcoming_locked' when progress.status='completed'then'view_scorecard'else item.game->>'nextAction'end,'canConfirm',case when progress.status='current'then(item.game->>'canConfirm')::boolean else false end)order by(item.game->>'eventName'),(item.game->>'gameNumber')::integer,(item.game->>'matchInstance')::integer)from jsonb_array_elements(payload->'games')item(game)join app.canonical_games game on game.id=(item.game->>'gameId')::uuid join app.event_participants participant on participant.id in(game.side_a_participant_id,game.side_b_participant_id)and participant.profile_id=(select auth.uid())cross join lateral(select app.participant_game_progression_v1(game.id,participant.id)status)progress),'[]'::jsonb),false)end from base
$$;
revoke all on function public.get_my_assigned_games_v1(uuid) from public,anon;
grant execute on function public.get_my_assigned_games_v1(uuid) to authenticated;

notify pgrst,'reload schema';
